import{_ as l,h as n,i as a,c as i,v as t,p as s,x as o,m as p,e as E,S as d}from"./chunks/framework.Dvtg8yj2.js";const M=JSON.parse('{"title":"共享专家与细粒度专家","description":"","frontmatter":{"title":"共享专家与细粒度专家","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/shared-expert-moe.md","filePath":"llm/shared-expert-moe.md","lastUpdated":1788454257000}'),h={name:"llm/shared-expert-moe.md"};function k(m,e,_,x,c,A){const r=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="共享专家与细粒度专家" tabindex="-1">共享专家与细粒度专家 <a class="header-anchor" href="#共享专家与细粒度专家" aria-label="Permalink to &quot;共享专家与细粒度专家&quot;">​</a></h1><div class="epigraph"><p>公共知识不该每次都重新路由；专业化则该切得更碎，好让 top-k 的组合数变多。</p><footer>—— DeepSeek-V2 / V3 技术报告，2024–2025；对照 Qwen2-MoE 与 Mixtral</footer></div><p>Mixtral 把 FFN 换成 8 个同等大小的专家，每个 token 取 top-2，没有永远在线的共享专家。这条路简单，但所有知识——包括几乎每个 token 都要用的句法、停用词、浅层变换——都得挤进被路由的专家里，路由既要管「公共件」又要管「专项件」。DeepSeekMoE 与 Qwen 的 MoE 变体把专家分成两类：<strong>共享专家</strong>（shared experts）对每个 token 必算；<strong>细粒度路由专家</strong>把原来一个大 FFN 切成多份小专家，同样激活参数下 top-\\(k\\) 的组合更多。本篇讲这种切法的动机与机制，具体的 DeepSeek 规模与训练并行放在下一篇。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准 MoE 假设专家对称：任意 token 都可以、也只通过路由去找专家。对称有两个缺点。第一，公共变换没有安放处。若每个专家都学一份「通用 MLP」，参数重复，稀疏度是假的。若没有人学通用部分，路由必须把通用 token 均匀洒开，专业化被稀释。第二，专家粒度过粗时，组合数不足。8 选 2 只有 28 种无序对；把一个大专家切成 4 个小专家，同样激活参数下可选组合指数上升，路由能表达更细的技能拼装。</p><h3 id="共享与细粒度是两个旋钮" tabindex="-1">共享与细粒度是两个旋钮 <a class="header-anchor" href="#共享与细粒度是两个旋钮" aria-label="Permalink to &quot;共享与细粒度是两个旋钮&quot;">​</a></h3><p>共享专家解决「公共知识放哪」；细粒度解决「同样 FLOPs 下组合数够不够」。可以只用其中之一：有的模型加共享专家但专家仍很肥；有的只把专家切小、不设共享。DeepSeek 与 Qwen2-MoE 选择两者一起用，是因为中文与代码、多语言混训时，公共层很重，同时任务又需要很多专项组合。<span class="marginnote">共享专家不是「多一个稠密 FFN 当残差」。它和路由专家同一层、同一残差槽位，输出相加。每个 token 的激活参数 = 共享专家参数 + \\(k\\) 个小专家参数，设计时要按这个和去对齐 Mixtral 式激活量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记共享专家为 \\(S_1,\\ldots,S_m\\)（\\(m\\) 常为 1 或 2，Qwen1.5-MoE 用过 4），路由专家为 \\(E_1,\\ldots,E_N\\)，\\(N\\) 远大于 Mixtral 的 8。对 token \\(x\\)，</p> \\[y=\\sum_{j=1}^{m}S_j(x)+\\sum_{i\\in\\mathrm{top}\\text{-}k}\\tilde{p}_i\\,E_i(x). \\]<p>共享支路没有离散选择，梯度完整。路由支路仍走 softmax + top-\\(k\\) + 负载均衡。细粒度意味着每个 \\(E_i\\) 的中间维是稠密 FFN 的 \\(1/n\\)，例如把原来 4 倍中间维切成 \\(n\\) 份，再设 \\(N\\) 为数倍于 \\(n\\) 的专家数，使激活的中间维总和与稠密模型接近。</p>',11)),(a(),s(d,null,{default:o(()=>[E(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22token%20x%22%5D%20--%3E%20SH%5B%22%E5%A7%8B%E7%BB%88%E8%AE%A1%E7%AE%97%E7%9A%84%E5%85%B1%E4%BA%AB%E4%B8%93%E5%AE%B6%22%5D%0A%20%20X%20--%3E%20RT%5B%22%E8%B7%AF%E7%94%B1%E5%88%B0%20k%20%E4%B8%AA%E5%B0%8F%E4%B8%93%E5%AE%B6%22%5D%0A%20%20SH%20--%3E%20ADD%5B%22%E8%BE%93%E5%87%BA%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20RT%20--%3E%20ADD%0A%20%20ADD%20--%3E%20Y%5B%22MoE%20%E5%B1%82%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="对照-mixtral-与-qwen2-moe" tabindex="-1">对照 Mixtral 与 Qwen2-MoE <a class="header-anchor" href="#对照-mixtral-与-qwen2-moe" aria-label="Permalink to &quot;对照 Mixtral 与 Qwen2-MoE&quot;">​</a></h3><p>Mixtral 8×7B：8 个对称专家，top-2，无共享。组合数少，实现与推理友好，EP 往往可省略。Qwen2-57B-A14B 一类 Qwen2-MoE：专家数到几十，并引入共享专家，激活参数约 14B，总参数远大于激活。细粒度体现在「更多更小的专家 + 较大的 \\(k\\)」，而不是 Switch 那种极稀疏的 \\(k=1\\)。共享专家吸收所有 token 都需要的变换，路由专家更可能变成领域、语言或模式专项。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>从优化看，共享专家的梯度是全部 token 的平均，方差小、更新稳，适合学高频、低变异的映射。路由专家的梯度只来自被选中的子集，方差大，适合学长尾。若没有共享支路，高频映射会污染所有专家，长尾专家也得先拟合一份「通用 FFN」才能开始专项，这浪费容量。</p><h3 id="组合数" tabindex="-1">组合数 <a class="header-anchor" href="#组合数" aria-label="Permalink to &quot;组合数&quot;">​</a></h3><p>激活 \\(k\\) 个细粒度专家，无序组合数为 \\(\\binom{N}{k}\\)。\\(N=8,k=2\\) 时是 28；\\(N=64,k=6\\) 时已经是数百万量级。模型并不会用满所有组合，但路由超平面可以把输入空间切得更碎。代价是：专家更小，单个专家的表达力下降，必须靠组合；通信上 All-to-All 的对端和 \\(k\\) 都涨，需要设备限制路由（一个 token 只访问少数节点上的专家）。负载均衡也更难，因为 \\(N\\) 大、\\(f_i\\) 更稀疏。</p><p>共享专家的宽度是隐形超参。太宽，激活 FLOPs 被共享支路占满，稀疏优势消失；太窄，公共知识仍挤进路由专家。实践中共享部分往往占激活 FFN 的一小半或更少，让路由专家仍主导容量。<span class="marginnote">细粒度不是把 MoE 做成另一种注意力。组合发生在 FFN 槽位，token 之间仍然只靠注意力交互。专家组合再多，也做不了 \\(n^2\\) 的检索。写「细粒度 MoE 替代注意力」是范畴错误。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>共享 + 细粒度增加实现与并行复杂度，小模型上常常不值得。几亿参数的学生模型，一个稠密 SwiGLU 更干净。Mixtral 证明 8 专家 top-2 在开源 7B 级已经很强；只有总参数要拉到百亿、千亿且推理预算锁死在激活量时，才需要把专家切碎并抽出共享支路。</p><p>共享专家会让「稀疏度」宣传变得含糊。必须同时报：总参数、激活参数、共享专家数、路由专家数、\\(k\\)。只报总参数是误导；只报 \\(k/N\\) 而忽略共享支路，会低估每次前向的真实 FLOPs。</p><p>Qwen2-MoE 与 DeepSeekMoE 的共享数量、专家宽度并不相同，不能把一家的超参抄到另一家的权重上。微调时冻结共享专家、只训路由专家，或相反，会得到完全不同的适应行为：前者改专项、后者改所有 token 的基底。这些是边界上的训推选择，不是架构定义的一部分。</p><p>共享专家的初始化也值得单独说。若把共享支路初始化成与稠密 FFN 相同的尺度，而路由专家更窄，早期训练会几乎只走共享支路，路由 logits 学得很慢。反过来，共享太弱，公共变换仍渗进各个小专家，细粒度的组合优势要到很晚才出现。一种稳妥策略是：共享专家宽度取激活中间维的一小部分，学习率与路由专家相同，让两条支路一起动。推理时共享专家没有离散选择，可以常驻 HBM，路由专家再按需换入；这与「全部专家对等、都可能被换出」的 Mixtral 式缓存策略不同，调度器必须认识 shared 这一类。<span class="marginnote">组合数 \\(\\binom{N}{k}\\) 是上限，不是利用率。真正被频繁用到的专家子集往往远小于这个数。评测长尾能力时，应看冷专家是否仍有非零 \\(f_i\\)，而不是只看平均损失。</span>把细粒度专家再叠一层「专家选专家」会变成层级 MoE，通信和负载问题加倍；在共享 + 单层 top-\\(k\\) 还没做稳之前，不必往那走。本篇的边界就是：共享管公共知识，细粒度管组合数，两件事已经够重。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享专家对每个 token 必算，用来吸收公共知识，避免通用 MLP 在所有专家里重复。</li><li>细粒度专家把大 FFN 切小、增多，使同样激活量下 top-\\(k\\) 组合数大幅上升。</li><li>Mixtral 是对称少专家、无共享的对照；Qwen2-MoE 与 DeepSeek 走共享 + 多专家。</li><li>激活参数 = 共享 + \\(k\\) 个小专家，设计必须按这个和对齐预算。</li><li>\\(N\\) 变大后负载均衡与 All-to-All 更难，常需设备限制路由。</li><li>出处：DeepSeek-V2 / V3 技术报告（DeepSeekMoE），2024–2025；Qwen2 技术报告中的 MoE 变体；Mixtral 作为对称 MoE 对照。</li></ul>',14))])}const u=l(h,[["render",k]]);export{M as __pageData,u as default};
